package com.pollhub.service;import com.pollhub.entity.User;import com.pollhub.repository.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import java.util.Optional;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class AdminServiceTest{@Mock UserRepository users;@Mock PollRepository polls;@Mock VoteRepository votes;@InjectMocks AdminService service;@Test void disablesUser(){User u=new User();u.setId(1L);u.setEnabled(true);when(users.findById(1L)).thenReturn(Optional.of(u));assertFalse(service.setEnabled(1L,false).enabled());}}
